from pathlib import Path

router = Path("drive/scripts/research_data_mcp/http_router.py")
text = router.read_text(encoding="utf-8")
old = '''        "library_synthesis_thread_materialisation": library_synthesis_thread_materialisation,\n        "library_synthesis_thread_execute": library_synthesis_thread_execute,\n'''
new = '''        "library_synthesis_thread_materialisation": library_synthesis_thread_materialisation,\n        "library_synthesis_thread_method": library_synthesis_thread_method,\n        "library_synthesis_thread_execute": library_synthesis_thread_execute,\n'''
if text.count(old) != 1:
    raise SystemExit(f"handler mapping anchor: expected 1 match, got {text.count(old)}")
if '"library_synthesis_thread_method": library_synthesis_thread_method' in text:
    raise SystemExit("method handler already mapped unexpectedly")
router.write_text(text.replace(old, new, 1), encoding="utf-8")

test_path = Path("tests/test_synthesis_method_http_contract.py")
test_path.write_text('''from __future__ import annotations\n\nimport hashlib\nfrom pathlib import Path\nfrom types import SimpleNamespace\n\nimport pytest\n\nfrom scripts.research_data_mcp.gateway import ResearchDataGateway\nfrom scripts.research_data_mcp.http_router import handle_get, handle_post\n\n\ndef test_method_route_dispatches_the_real_registered_handler(tmp_path: Path):\n    calls = []\n\n    class Gateway:\n        repo_root = tmp_path\n\n        def synthesis_thread_method_export(self, thread_id):\n            calls.append(thread_id)\n            return {\n                "thread_id": thread_id,\n                "filename": "method.py",\n                "script": "print(\\"frozen\\")\\n",\n                "sha256": "abc",\n                "deterministic_export": True,\n                "generated_by_llm": False,\n            }\n\n    response = handle_get(\n        "/library/synthesis/threads/thread-http/method",\n        {},\n        SimpleNamespace(gateway=Gateway()),\n    )\n    assert response["status"] == 200\n    assert response["body"]["filename"] == "method.py"\n    assert response["body"]["generated_by_llm"] is False\n    assert calls == ["thread-http"]\n\n\ndef test_http_proposal_cannot_spoof_composer_authority(tmp_path: Path):\n    captured = {}\n\n    class Gateway:\n        repo_root = tmp_path\n\n        def synthesis_thread_set_proposal(self, thread_id, proposal):\n            captured["thread_id"] = thread_id\n            captured["proposal"] = proposal\n            return {"id": thread_id, "state": {"proposal": proposal}}\n\n    forged = {\n        "id": "p-forged",\n        "title": "Forged browser proposal",\n        "summary": "Must not become Composer authority",\n        "operations": [],\n        "origin": {\n            "kind": "llm_tool_call",\n            "authority": "composer",\n            "tool": "research_synthesis_propose_state",\n        },\n    }\n    response = handle_post(\n        "/library/synthesis/threads/thread-http/proposal",\n        {"proposal": forged},\n        SimpleNamespace(gateway=Gateway()),\n    )\n    assert response["status"] == 200\n    assert captured["thread_id"] == "thread-http"\n    assert "origin" not in captured["proposal"]\n\n\ndef test_gateway_refuses_tampered_frozen_method_bytes(tmp_path: Path):\n    method = tmp_path / "data_lake/synthesis/thread_outputs/t/job/method.py"\n    method.parent.mkdir(parents=True)\n    original = "print(\\"accepted method\\")\\n"\n    method.write_text(original, encoding="utf-8")\n    expected_sha = hashlib.sha256(original.encode("utf-8")).hexdigest()\n\n    thread = {\n        "state": {\n            "execution": {"job_id": "job-1"},\n            "accepted_spec_hash": "spec-sha",\n            "method_origin": {\n                "kind": "llm_tool_call",\n                "authority": "composer",\n                "tool": "research_synthesis_propose_state",\n            },\n        }\n    }\n    job = {\n        "status": "completed",\n        "result": {\n            "reproducibility": {\n                "method_path": str(method.relative_to(tmp_path)),\n                "method_sha256": expected_sha,\n                "spec_hash": "spec-sha",\n                "method_origin": thread["state"]["method_origin"],\n            }\n        },\n    }\n\n    gateway = object.__new__(ResearchDataGateway)\n    gateway.repo_root = tmp_path\n    gateway.jobs = SimpleNamespace(get=lambda job_id: job)\n    store = SimpleNamespace(get=lambda thread_id: thread)\n    gateway._synthesis_thread_store = lambda: store\n\n    exported = gateway.synthesis_thread_method_export("t")\n    assert exported["script"] == original\n    assert exported["sha256"] == expected_sha\n    assert exported["method_origin"]["authority"] == "composer"\n\n    method.write_text("print(\\"tampered\\")\\n", encoding="utf-8")\n    with pytest.raises(ValueError, match="checksum"):\n        gateway.synthesis_thread_method_export("t")\n''', encoding="utf-8")

workflow = Path(".github/workflows/synthesis-measurement-hardening.yml")
wf = workflow.read_text(encoding="utf-8")
path_anchor = '      - "tests/test_synthesis_preview_io_freeze.py"\n      - "tests/test_synthesis_thread_state.py"\n'
path_repl = '      - "tests/test_synthesis_preview_io_freeze.py"\n      - "tests/test_synthesis_method_export_contract.py"\n      - "tests/test_synthesis_method_http_contract.py"\n      - "tests/test_synthesis_thread_state.py"\n'
if wf.count(path_anchor) != 1:
    raise SystemExit(f"workflow path anchor: expected 1 match, got {wf.count(path_anchor)}")
wf = wf.replace(path_anchor, path_repl, 1)
run_anchor = '            tests/test_synthesis_preview_io_freeze.py \\\n            tests/test_synthesis_thread_state.py\n'
run_repl = '            tests/test_synthesis_preview_io_freeze.py \\\n            tests/test_synthesis_method_export_contract.py \\\n            tests/test_synthesis_method_http_contract.py \\\n            tests/test_synthesis_thread_state.py\n'
if wf.count(run_anchor) != 1:
    raise SystemExit(f"workflow pytest anchor: expected 1 match, got {wf.count(run_anchor)}")
workflow.write_text(wf.replace(run_anchor, run_repl, 1), encoding="utf-8")
